import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import stringToColor from 'flarum/common/utils/stringToColor';
import classList from 'flarum/common/utils/classList';
import { t } from '../util';

/*
 * The pieces every widget and page draws a testimonial with. Colours come from Flarum's CSS
 * properties (less/forum.less), so themes and dark mode carry through.
 */

function StarsView(attrs) {
  const value = attrs.value ?? 0;
  if (!value) return null;
  const full = Math.round(value * 2) / 2;
  return m("span", {
    className: classList('TestimonialStars', `TestimonialStars--${attrs.size || 'sm'}`),
    role: "img",
    "aria-label": t('stars_label', {
      rating: value
    })
  }, [1, 2, 3, 4, 5].map(i => m("span", {
    className: classList('TestimonialStars-star', i <= full ? 'is-on' : i - 0.5 === full ? 'is-half' : ''),
    "aria-hidden": "true"
  }, "\u2605")));
}
function AvatarView(attrs) {
  const author = attrs.row.author();
  const size = attrs.size || 36;
  const style = {
    width: `${size}px`,
    height: `${size}px`,
    fontSize: `${Math.round(size * 0.38)}px`
  };
  if (author.anonymous) {
    return m("span", {
      className: "TestimonialAvatar TestimonialAvatar--anonymous",
      style: style,
      "aria-hidden": "true"
    }, m(Icon, {
      name: "fas fa-user"
    }));
  }
  if (author.avatarUrl) return m("img", {
    className: "TestimonialAvatar",
    src: author.avatarUrl,
    alt: "",
    loading: "lazy",
    style: style
  });
  const name = author.name || '?';
  return m("span", {
    className: "TestimonialAvatar",
    style: {
      ...style,
      '--avatar-bg': `#${stringToColor(name)}`
    },
    "aria-hidden": "true"
  }, name.charAt(0).toUpperCase());
}
function BylineView(attrs) {
  const row = attrs.row;
  const author = row.author();
  const name = author.anonymous ? t('byline.anonymous') : author.name;
  const subject = row.subject();
  return m("div", {
    className: "TestimonialByline"
  }, m(Avatar, {
    row: row,
    size: attrs.size
  }), m("div", {
    className: "TestimonialByline-text"
  }, author.username ? m(Link, {
    className: "TestimonialByline-name",
    href: app.route('user', {
      username: author.username
    })
  }, name) : m("span", {
    className: "TestimonialByline-name"
  }, name), m("span", {
    className: "TestimonialByline-meta"
  }, author.since ? t('byline.since', {
    year: author.since
  }) : null, attrs.withSubject && subject.label ? [author.since ? ' · ' : '', subject.label] : null)));
}

/** What it's about, as a small chip (a link where there is one). */
function SubjectChipView(attrs) {
  const subject = attrs.row.subject();
  const label = subject.type === 'community' ? t('subject.community') : subject.label;
  if (!label) return null;
  return subject.url ? m("a", {
    className: "TestimonialChip",
    href: subject.url
  }, label) : m("span", {
    className: "TestimonialChip"
  }, label);
}

/** A testimonial as a card: the wall, the page and the queue all use it. */
function CardView(attrs) {
  const row = attrs.row;
  return m("article", {
    className: classList('TestimonialCard', attrs.large && 'TestimonialCard--large', row.isFeatured() && 'is-featured', attrs.className)
  }, m("div", {
    className: "TestimonialCard-top"
  }, attrs.showRating !== false ? m(Stars, {
    value: row.rating()
  }) : null, m(SubjectChip, {
    row: row
  })), attrs.large ? m(QuoteMark, null) : null, row.headline() ? m("h3", {
    className: "TestimonialCard-headline"
  }, row.headline()) : null, m("p", {
    className: "TestimonialCard-body"
  }, row.body()), m(Byline, {
    row: row,
    size: attrs.large ? 40 : 32
  }), attrs.footer);
}
function QuoteMarkView(_attrs) {
  return m("svg", {
    className: "TestimonialQuoteMark",
    width: "28",
    height: "22",
    viewBox: "0 0 28 22",
    "aria-hidden": "true"
  }, m("path", {
    d: "M0 22V13.2C0 5.6 4 1.2 11 0l1 3.4C8 4.6 6.3 7 6.2 10.4H11V22zm16 0V13.2C16 5.6 20 1.2 27 0l1 3.4c-4 1.2-5.7 3.6-5.8 7H27V22z"
  }));
}

// Each view as a Flarum component, so JSX and the typings take it like any other.

export class Stars extends Component {
  view() {
    return StarsView(this.attrs);
  }
}
export class Avatar extends Component {
  view() {
    return AvatarView(this.attrs);
  }
}
export class Byline extends Component {
  view() {
    return BylineView(this.attrs);
  }
}
export class SubjectChip extends Component {
  view() {
    return SubjectChipView(this.attrs);
  }
}
export class Card extends Component {
  view() {
    return CardView(this.attrs);
  }
}
export class QuoteMark extends Component {
  view() {
    return QuoteMarkView({});
  }
}

/* The rating summary's pieces, on the rating widget and the testimonials page. */

export class RatingScore extends Component {
  view() {
    const data = this.attrs.summary;
    return m("div", {
      className: "TestimonialsRating-score"
    }, m("span", {
      className: "TestimonialsRating-average"
    }, (data.average || 0).toFixed(1)), m("span", {
      className: "TestimonialsRating-of"
    }, m(Stars, {
      value: data.average,
      size: "md"
    }), m("span", null, t('widget.count', {
      count: data.count
    }))));
  }
}

/** The 5→1 spread, each bar against the most common rating. */
export class RatingBars extends Component {
  view() {
    const data = this.attrs.summary;
    const max = Math.max(1, ...Object.values(data.spread));
    return m("div", {
      className: "TestimonialsRating-bars"
    }, [5, 4, 3, 2, 1].map(n => m("div", {
      className: "TestimonialsRating-bar"
    }, m("span", null, n), m("span", {
      className: "TestimonialsRating-track"
    }, m("span", {
      style: {
        width: `${Math.round((data.spread[n] || 0) / max * 100)}%`
      }
    })), m("span", null, data.spread[n] || 0))));
  }
}
export class RatingAspects extends Component {
  view() {
    return m("dl", {
      className: "TestimonialsRating-aspects"
    }, this.attrs.summary.aspects.map(a => m("div", {
      className: "TestimonialsRating-aspect"
    }, m("dt", null, a.name), m("dd", null, m("span", {
      className: "TestimonialsRating-track"
    }, m("span", {
      style: {
        width: `${a.average / 5 * 100}%`
      }
    })), m("span", null, a.average.toFixed(1))))));
  }
}

/*
 * Narrow spots (sidebars, a third-width column, FoF's side sections) get the compact look,
 * decided by the widget's own width: one ResizeObserver for every widget on the page.
 */
let observer = null;
export function watchWidth(el) {
  if (typeof ResizeObserver === 'undefined') return;
  observer ??= new ResizeObserver(entries => {
    for (const entry of entries) {
      const width = entry.contentRect.width;
      entry.target.classList.toggle('is-compact', width > 0 && width < 520);
      entry.target.classList.toggle('is-narrow', width > 0 && width < 320);
    }
  });
  observer.observe(el);
}
export function unwatchWidth(el) {
  observer?.unobserve(el);
}
flarum.reg.add('ernestdefoe-testimonials', 'forum/widgets/ui', { Stars: Stars,Avatar: Avatar,Byline: Byline,SubjectChip: SubjectChip,Card: Card,QuoteMark: QuoteMark,RatingScore: RatingScore,RatingBars: RatingBars,RatingAspects: RatingAspects,watchWidth: watchWidth,unwatchWidth: unwatchWidth, });